    if (!remoteHasBranch) {
      if (debug) {
        console.error("[DEBUG] Shadow pull-rebase: no remote branch yet, skipping pull");
      }
      return true;
    }

    // Check if there are any upstream changes to integrate.
    // If local is already at or ahead of remote, skip the pull.
