export async function loadProjectConfig(
  startDir: string = process.cwd(),
): Promise<LoadConfigResult> {
  const gitRoot = findProjectRoot(startDir);

  if (!gitRoot) {
    // Not in a git repo, use defaults
    return {
      config: resolveConfig(null),
      configPath: null,
      warning: null,
      gitRoot: null,
    };
